import{_ as s,o as n,c as e,a0 as l}from"./chunks/framework.Cp0xpwNH.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"ARCHITECTURE.md","filePath":"ARCHITECTURE.md"}'),p={name:"ARCHITECTURE.md"};function i(r,a,o,t,c,d){return n(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>This repository separates educational content from educational data.</p><hr><h2 id="three-layers" tabindex="-1">Three Layers <a class="header-anchor" href="#three-layers" aria-label="Permalink to &quot;Three Layers&quot;">​</a></h2><h3 id="layer-1-content" tabindex="-1">Layer 1: Content <a class="header-anchor" href="#layer-1-content" aria-label="Permalink to &quot;Layer 1: Content&quot;">​</a></h3><p>Learner-facing educational material.</p><ul><li>Lessons</li><li>Dialogues</li><li>Reading exercises</li><li>Writing prompts</li><li>Speaking exercises</li><li>Listening comprehension</li><li>Quizzes and exercises</li><li>Reviews</li><li>Assessments</li></ul><p><strong>Location:</strong> <code>A0/</code>, <code>A1/</code>, <code>A2/</code>, <code>B1/</code></p><h3 id="layer-2-data" tabindex="-1">Layer 2: Data <a class="header-anchor" href="#layer-2-data" aria-label="Permalink to &quot;Layer 2: Data&quot;">​</a></h3><p>The authoritative sources for grammar and vocabulary.</p><ul><li>Grammar explanations (referenced by lessons)</li><li>Vocabulary database (source of truth for all vocabulary)</li><li>Lesson metadata (dependencies, prerequisites)</li><li>Progression tracking (what comes before/after each concept)</li></ul><p><strong>Location:</strong> <code>shared/grammar/</code>, <code>shared/vocabulary/</code>, <code>shared/csv/</code></p><h3 id="layer-3-documentation" tabindex="-1">Layer 3: Documentation <a class="header-anchor" href="#layer-3-documentation" aria-label="Permalink to &quot;Layer 3: Documentation&quot;">​</a></h3><p>Standards, specifications, and guidelines.</p><ul><li>Curriculum principles (highest-precedence document)</li><li>Teaching philosophy</li><li>CEFR scope guide</li><li>Competency map</li><li>Curriculum roadmap</li><li>Grammar progression map</li><li>Vocabulary progression roadmap</li><li>Lesson standards (template and requirements)</li><li>Grammar explanation standards</li><li>Vocabulary entry standards</li><li>Quality assurance rules</li><li>Style guide</li><li>AI guidelines</li></ul><p><strong>Location:</strong> <code>docs/</code></p><hr><h2 id="content-hierarchy-competency-driven-not-lesson-count-driven" tabindex="-1">Content Hierarchy: Competency-Driven, Not Lesson-Count-Driven <a class="header-anchor" href="#content-hierarchy-competency-driven-not-lesson-count-driven" aria-label="Permalink to &quot;Content Hierarchy: Competency-Driven, Not Lesson-Count-Driven&quot;">​</a></h2><p>Content is not organized as a flat <code>Level -&gt; Module -&gt; Lesson</code> list sized in advance. It is organized around competencies (real-world abilities), and the number of units/lessons is a byproduct of what each competency requires:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CEFR Level (A0 / A1 / A2 / B1)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Competency (a real-world ability, e.g. &quot;Shopping&quot;)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Unit (the lessons that build one competency, e.g. &quot;Numbers and Prices&quot;)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Lesson (the smallest instructional block, follows LESSON_STANDARD.md)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Exercises</span></span></code></pre></div><p><strong>See:</strong> <code>docs/COMPETENCY_MAP.md</code> for the authoritative list of competencies per level and <code>docs/CURRICULUM_PRINCIPLES.md</code> for why this model was chosen over a fixed lesson count.</p><hr><h2 id="the-principle-never-duplicate" tabindex="-1">The Principle: Never Duplicate <a class="header-anchor" href="#the-principle-never-duplicate" aria-label="Permalink to &quot;The Principle: Never Duplicate&quot;">​</a></h2><h3 id="grammar" tabindex="-1">Grammar <a class="header-anchor" href="#grammar" aria-label="Permalink to &quot;Grammar&quot;">​</a></h3><p>Grammar explanations exist only once, in <code>shared/grammar/</code>.</p><p>When a lesson needs to explain grammar, it references the grammar file:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>**See:** \`/shared/grammar/personal-pronouns.md\`</span></span></code></pre></div><p>If you need to update a grammar explanation, you update it once in the shared file.</p><p>All lessons using that grammar automatically get the updated explanation.</p><h3 id="vocabulary" tabindex="-1">Vocabulary <a class="header-anchor" href="#vocabulary" aria-label="Permalink to &quot;Vocabulary&quot;">​</a></h3><p>Vocabulary exists only once, in <code>shared/vocabulary/master.csv</code>.</p><p>Every vocabulary item has:</p><ul><li>Dutch word</li><li>English translation</li><li>Article (de/het)</li><li>Plural form</li><li>Pronunciation</li><li>Part of speech</li><li>CEFR level</li><li>Lesson introduced</li><li>Frequency</li><li>Topic</li><li>Example sentence</li><li>Example translation</li><li>Notes</li></ul><p>When a lesson needs vocabulary, it either:</p><ol><li>References the master file: <code>**See:** </code>/shared/vocabulary/master.csv<code> (filter by lesson A0-01)</code></li><li>Generates a CSV export for the lesson</li><li>Embeds references to specific vocabulary entries</li></ol><p>Vocabulary CSVs are generated from the master, never maintained separately.</p><h3 id="lessons" tabindex="-1">Lessons <a class="header-anchor" href="#lessons" aria-label="Permalink to &quot;Lessons&quot;">​</a></h3><p>Lessons follow a standard template and reference external data.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## Grammar</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**See:** \`/shared/grammar/personal-pronouns.md\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Vocabulary</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| Dutch | English | Article |</span></span>
<span class="line"><span>|-------|---------|---------|</span></span>
<span class="line"><span>| ik | I | -- |</span></span>
<span class="line"><span>| jij | you (informal) | -- |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(Reference to master database)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Dialogue</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Sample dialogue using only known grammar and vocabulary]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Exercises</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Exercises using only known grammar and vocabulary]</span></span></code></pre></div><p>Lessons never contain full grammar explanations or vocabulary definitions.</p><hr><h2 id="data-flow" tabindex="-1">Data Flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data Flow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Master Vocabulary CSV</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>    ├→ Vocabulary files (shared/vocabulary/)</span></span>
<span class="line"><span>    ├→ CSV exports for each lesson</span></span>
<span class="line"><span>    ├→ Anki deck generation</span></span>
<span class="line"><span>    └→ Vocabulary roadmap</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Grammar Files</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>    ├→ Lessons (reference)</span></span>
<span class="line"><span>    ├→ Grammar map</span></span>
<span class="line"><span>    └→ Review lessons</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Competency Map</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>    ├→ Curriculum Map (units and lessons generated from competencies)</span></span>
<span class="line"><span>    ├→ Grammar Map (grammar required per competency)</span></span>
<span class="line"><span>    └→ Vocabulary Roadmap (vocabulary required per competency)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Curriculum Map</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>    ├→ Lesson files (A0/, A1/, A2/, B1/)</span></span>
<span class="line"><span>    ├→ Review schedules</span></span>
<span class="line"><span>    ├→ Dependencies</span></span>
<span class="line"><span>    └→ Assessment requirements</span></span></code></pre></div><hr><h2 id="relationships" tabindex="-1">Relationships <a class="header-anchor" href="#relationships" aria-label="Permalink to &quot;Relationships&quot;">​</a></h2><h3 id="lessons-reference" tabindex="-1">Lessons Reference <a class="header-anchor" href="#lessons-reference" aria-label="Permalink to &quot;Lessons Reference&quot;">​</a></h3><ul><li><code>docs/CURRICULUM_PRINCIPLES.md</code> -- For the highest-level rationale (checked first in a conflict)</li><li><code>docs/COMPETENCY_MAP.md</code> -- For the competency and unit this lesson belongs to</li><li><code>docs/CURRICULUM.md</code> -- For dependencies and prerequisites</li><li><code>docs/GRAMMAR_MAP.md</code> -- For what grammar is available</li><li><code>docs/VOCABULARY_ROADMAP.md</code> -- For what vocabulary is planned</li><li><code>shared/grammar/</code> -- For grammar explanations</li><li><code>shared/vocabulary/master.csv</code> -- For vocabulary definitions</li></ul><h3 id="reviews-reference" tabindex="-1">Reviews Reference <a class="header-anchor" href="#reviews-reference" aria-label="Permalink to &quot;Reviews Reference&quot;">​</a></h3><ul><li>Previous lessons (what to review)</li><li><code>docs/REVIEW_STRATEGY.md</code> -- For review structure</li></ul><h3 id="grammar-map-references" tabindex="-1">Grammar Map References <a class="header-anchor" href="#grammar-map-references" aria-label="Permalink to &quot;Grammar Map References&quot;">​</a></h3><ul><li><code>docs/COMPETENCY_MAP.md</code> -- For which competency requires this grammar</li><li><code>docs/CURRICULUM.md</code> -- For lesson numbers</li><li><code>shared/grammar/</code> -- For full explanations</li></ul><h3 id="vocabulary-roadmap-references" tabindex="-1">Vocabulary Roadmap References <a class="header-anchor" href="#vocabulary-roadmap-references" aria-label="Permalink to &quot;Vocabulary Roadmap References&quot;">​</a></h3><ul><li><code>docs/COMPETENCY_MAP.md</code> -- For which competency requires this vocabulary</li><li><code>docs/CURRICULUM.md</code> -- For lesson placement</li><li><code>shared/vocabulary/master.csv</code> -- For actual vocabulary</li></ul><hr><h2 id="file-organization" tabindex="-1">File Organization <a class="header-anchor" href="#file-organization" aria-label="Permalink to &quot;File Organization&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Dutch-B1-Curriculum/</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── README.md                    (Start here)</span></span>
<span class="line"><span>├── PROJECT.md                   (Philosophy)</span></span>
<span class="line"><span>├── ROADMAP.md                   (Development phases)</span></span>
<span class="line"><span>├── LICENSE.md                   (Legal)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── docs/                        (Documentation &amp; Standards)</span></span>
<span class="line"><span>│   ├── ARCHITECTURE.md          (This file)</span></span>
<span class="line"><span>│   ├── CURRICULUM_PRINCIPLES.md (Highest-precedence document)</span></span>
<span class="line"><span>│   ├── TEACHING_PHILOSOPHY.md   (Pedagogical approach)</span></span>
<span class="line"><span>│   ├── CEFR_GUIDE.md            (CEFR scope: grammar/vocab/skills per level)</span></span>
<span class="line"><span>│   ├── COMPETENCY_MAP.md        (Competencies per level -- drives everything below)</span></span>
<span class="line"><span>│   ├── CURRICULUM.md            (Unit/lesson roadmap, generated from Competency Map)</span></span>
<span class="line"><span>│   ├── GRAMMAR_MAP.md           (Grammar progression)</span></span>
<span class="line"><span>│   ├── VOCABULARY_ROADMAP.md    (Vocab progression)</span></span>
<span class="line"><span>│   ├── LESSON_STANDARD.md       (Template &amp; rules)</span></span>
<span class="line"><span>│   ├── GRAMMAR_STANDARD.md      (Grammar format)</span></span>
<span class="line"><span>│   ├── VOCABULARY_STANDARD.md   (Vocab format)</span></span>
<span class="line"><span>│   ├── REVIEW_STRATEGY.md       (Review structure)</span></span>
<span class="line"><span>│   ├── STYLE_GUIDE.md           (Formatting rules)</span></span>
<span class="line"><span>│   ├── QUALITY_CHECKLIST.md     (QA checklist)</span></span>
<span class="line"><span>│   ├── AI_GUIDELINES.md         (AI rules)</span></span>
<span class="line"><span>│   └── CHANGELOG.md             (Version history)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── agents/                      (AI agent definitions)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── shared/                      (Shared data &amp; templates)</span></span>
<span class="line"><span>│   ├── grammar/                 (Grammar reference files)</span></span>
<span class="line"><span>│   │   ├── personal-pronouns.md</span></span>
<span class="line"><span>│   │   ├── present-tense.md</span></span>
<span class="line"><span>│   │   └── [more grammar files]</span></span>
<span class="line"><span>│   ├── vocabulary/              (Vocabulary master)</span></span>
<span class="line"><span>│   │   ├── master.csv           (Single source of truth)</span></span>
<span class="line"><span>│   │   ├── A0.csv               (A0 filtered export)</span></span>
<span class="line"><span>│   │   ├── A1.csv               (A1 filtered export)</span></span>
<span class="line"><span>│   │   └── [more exports]</span></span>
<span class="line"><span>│   ├── templates/                (Content templates)</span></span>
<span class="line"><span>│   ├── prompts/                  (AI prompts, including research prompts)</span></span>
<span class="line"><span>│   ├── assets/                   (Images, audio, etc)</span></span>
<span class="line"><span>│   └── csv/                      (Generated CSVs)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── A0/                          (Foundations level)</span></span>
<span class="line"><span>│   ├── README.md</span></span>
<span class="line"><span>│   ├── Competency-1-&lt;Name&gt;/</span></span>
<span class="line"><span>│   │   ├── Unit-1-&lt;Name&gt;/</span></span>
<span class="line"><span>│   │   │   ├── A0-01.md</span></span>
<span class="line"><span>│   │   │   └── A0-02.md</span></span>
<span class="line"><span>│   │   └── Unit-2-&lt;Name&gt;/</span></span>
<span class="line"><span>│   ├── Competency-2-&lt;Name&gt;/</span></span>
<span class="line"><span>│   ├── Reviews/</span></span>
<span class="line"><span>│   ├── Quizzes/</span></span>
<span class="line"><span>│   └── Assessment/</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── A1/                          (Beginner level)</span></span>
<span class="line"><span>│   └── [Same structure as A0]</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── A2/                          (Elementary level)</span></span>
<span class="line"><span>│   └── [Same structure as A0]</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── B1/                          (Independent User level)</span></span>
<span class="line"><span>    └── [Same structure as A0]</span></span></code></pre></div><hr><h2 id="why-this-structure" tabindex="-1">Why This Structure? <a class="header-anchor" href="#why-this-structure" aria-label="Permalink to &quot;Why This Structure?&quot;">​</a></h2><ol><li><strong>Single Source of Truth</strong> -- Reduce inconsistency and make updates easier</li><li><strong>Scalability</strong> -- Add new lessons without affecting existing ones</li><li><strong>AI-Friendly</strong> -- Clear dependencies and reference patterns</li><li><strong>Maintainable</strong> -- Standards make it easy to update years later</li><li><strong>Reusability</strong> -- Grammar and vocabulary can be used by any lesson</li><li><strong>Trackability</strong> -- Dependencies are explicit and documented</li><li><strong>Competency-Driven</strong> -- Scope (Competency Map, CEFR Guide) is defined before size (units, lessons), so level size is always a byproduct of what learners need, never an arbitrary target</li></ol>`,59)])])}const h=s(p,[["render",i]]);export{u as __pageData,h as default};
